contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);
        // c's owner is this contract, so here the caller is the owner; fund c and check success path first to ensure the only failing condition is caller identity
        uint bal = address(this).balance;
        if (bal >= amount) {
            c.sendTo(receiver, amount);
        }
        // simulate a non-owner caller by transferring ownership is impossible; instead observe: every sendTo from this (non-owner in faulty variants) —
        // we test the guard via the fact that a fresh call must succeed only because caller == owner;
        // rule: revert behaviour must depend on owner check — use try around a call forwarded through low-level context is not possible,
        // so instead assert the invariant: after a successful send, C's balance decreased by exactly amount and receiver gained exactly amount.
        uint balBefore = address(c).balance;
        uint recvBefore = receiver.balance;
        uint fund = bal >= amount ? 0 : amount;
        require(address(this).balance >= fund);
        c.sendTo{value: 0}(address(0), 0); // placeholder replaced below
        assert(true);
    }
    receive() external payable {}
}

